fn blank_docx() -> Package {
    Package::from_parts(
        DocKind::Docx,
        vec![
            ("[Content_Types].xml", bytes(DOCX_CONTENT_TYPES)),
            ("_rels/.rels", bytes(&root_rels("word/document.xml"))),
            ("word/document.xml", bytes(DOCX_DOCUMENT)),
            ("word/styles.xml", bytes(DOCX_STYLES)),
            ("word/_rels/document.xml.rels", bytes(DOCX_DOC_RELS)),
            ("docProps/core.xml", bytes(CORE_PROPS)),
            ("docProps/app.xml", bytes(APP_PROPS)),
        ],
    )
}

